input.script:
users = list_users({})
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

entries = for user in users {
    avails = for date in dates {
        a = boundary retry 2 {
            return get_availability({ user_id: user.id, date: date })
        } catch err {
            return fail("AVAIL_FAILED", err.code + ": " + err.message)
        }
        return { date: date, busy: a.busy if a.busy != null else [] }
    }
    return { user_id: user.id, avails: avails }
}

slots_nested = for date in dates {
    inner = for hh in list.range(18, 33) {
        return { date: date, hh: hh }
    }
    return inner
}
slots = fold acc = [] for group in slots_nested {
    return acc + group
}

valid = for slot in slots {
    sm = slot.hh * 30
    em = sm + 60
    free_users = for entry in entries {
        matching = for a in entry.avails {
            skip if a.date != slot.date
            return a.busy
        }
        raw = matching[0] if matching != [] else []
        busy = raw if raw != null else []
        conflicts = for b in busy {
            bs_str = b.start if b.start != null else "00:00"
            be_str = b.end if b.end != null else "00:00"
            bsp = text.split(bs_str, ":")
            bep = text.split(be_str, ":")
            bs = number.parse(bsp[0]) * 60 + number.parse(bsp[1])
            be = number.parse(bep[0]) * 60 + number.parse(bep[1])
            skip if be <= bs
            skip if bs >= em
            skip if be <= sm
            return 1
        }
        skip if conflicts != []
        return entry.user_id
    }
    skip if list.length(free_users) != list.length(users)
    return slot
}

earliest = valid[0] if valid != [] else fail("NO_SLOT", "no 60-minute slot fits the whole team that week")

times = ["00:00","00:30","01:00","01:30","02:00","02:30","03:00","03:30","04:00","04:30","05:00","05:30","06:00","06:30","07:00","07:30","08:00","08:30","09:00","09:30","10:00","10:30","11:00","11:30","12:00","12:30","13:00","13:30","14:00","14:30","15:00","15:30","16:00","16:30","17:00"]

start_ts = text.join([earliest.date, "T", times[earliest.hh], ":00Z"], "")
end_ts = text.join([earliest.date, "T", times[earliest.hh + 2], ":00Z"], "")

result = submit_result({ answer: { start: start_ts, end: end_ts } })
return { start: start_ts, end: end_ts, recorded: result.recorded }
